# Administrative overviews assemble jurisdiction-specific facts from the detailed PDOs.
def admin(name,intro,outline,extras):
 a={'id':'it-'+name.lower(),'name':name,'country':'Italy','kind':'region','aliases':[],'intro':B(intro),'facts':[{'label':B('Country|国家'),'body':B('Italy|意大利')},{'label':B('Type|类型'),'body':B('Administrative region; individual DOC/DOCG boundaries are separate.|行政大区；各 DOC／DOCG 边界另行划定。')}],'sections':[],'grapes':[],'wines':[],'sources':[],'reviewed':'2026-10-26','questions':[],'coverage':B('Regional framework and selected denomination dossiers; not an exhaustive list of all PDOs.|地区框架及重点产区档案，非全部 PDO 完整清单。')}
 used={}
 for sid,title,parts in outline:
  rows=[];refs=[]
  for rid,subid in parts:
   rr=R[rid];ss=next(s for s in rr['sections'] if s['id']==subid)
   for row in ss['rows']:
    rows.append({'label':{'en':rr['name']+' — '+row['label']['en'],'zh':rr['name']+' — '+row['label']['zh']},'body':row['body']})
   refs+=ss['refs']
   for ssr in rr['sources']:used[ssr['id']]=ssr
  a['sections'].append({'id':sid,'title':B(title),'rows':rows,'refs':list(dict.fromkeys(refs))})
 for ss in extras:
  a['sections'].append(ss)
  for k in ss['refs']:used[k]={'id':k,'title':S[k][0],'url':S[k][1]}
 child=[r for r in D['regions'] if r.get('parentId')==a['id']]
 seen=set()
 for rr in child:
  for gg in rr['grapes']:
   if gg['grapeId'] not in seen:a['grapes'].append(gg.copy());seen.add(gg['grapeId'])
 for g in D['grapes']:
  if GREG[g['id']]!=name:continue
  src='grape-'+g['id'];used[src]={'id':src,'title':g['sources'][0]['title'],'url':g['sources'][0]['url']}
  if g['id'] not in seen:a['grapes'].append({'grapeId':g['id'],'role':B(next(t for t in D['translations'] if t['id']==g['id'])['summary']+'|'+g['summary']),'sourceIds':[src]});seen.add(g['id'])
 a['sources']=list(used.values());D['regions'].append(a);R[a['id']]=a
