def quiz(admin,text):
 r=R['it-'+admin.lower()]
 for n,line in enumerate(text.strip().splitlines(),1):
  q,a,src,group=line.split('^');srcs=src.split(',')
  for k in srcs:
   if not any(s['id']==k for s in r['sources']):r['sources'].append({'id':k,'title':S[k][0],'url':S[k][1]})
  r['questions'].append({'id':r['id']+'-q'+str(n).zfill(2),'level':'foundation' if n<=10 else 'advanced','group':group,'q':B(q),'a':B(a),'refs':srcs})
